-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Banco de Dados' and a.numero = 18
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 18 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 18', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 18 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/BANCO-DE-DADOS/ATIVIDADES/ATIVIDADE-PRATICA-AULA-18.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Diga o que é um trigger.', 0.2, 'É uma rotina que o banco **executa sozinho** quando acontece um **evento** (INSERT, UPDATE ou DELETE) numa **tabela**.', 'Nota cheia (0,2): executa sozinho + evento na tabela. Metade (0,1): só uma parte. Zero (0): sem relação.'),
      (v_atividade, 1, 2, 'Explique a diferença entre um trigger e um procedimento quanto a quem executa cada um.', 0.4, 'O **procedimento** é **chamado pelo sistema** (CALL ou SELECT); o **trigger** é executado **pelo próprio banco** quando o evento acontece, **sem ninguém chamar**.', 'Nota cheia (0,4): quem executa cada um. Metade (0,2): só um dos lados. Zero (0): invertido.'),
      (v_atividade, 1, 3, 'Explique por que o trigger protege a regra mesmo quando alguém altera a tabela direto pelo pgAdmin.', 0.4, 'Porque o trigger dispara para **qualquer comando na tabela**, venha do site, do aplicativo ou do **pgAdmin**; o procedimento só vale se alguém **lembrar de chamá-lo**.', 'Nota cheia (0,4): qualquer origem + comparação com o procedimento. Metade (0,2): só "vale para qualquer comando". Zero (0): sem relação.'),
      (v_atividade, 2, 1, 'Cite os três eventos que podem disparar um trigger de linha.', 0.2, '**INSERT**, **UPDATE** e **DELETE**.', 'Nota cheia (0,2): os três. Metade (0,1): dois. Zero (0): um ou nenhum, ou cita SELECT.'),
      (v_atividade, 2, 2, 'Explique a diferença entre BEFORE e AFTER, com um uso de cada.', 0.4, '**BEFORE** roda **antes** de gravar e pode **mudar ou barrar** a linha (ex.: validação da parcela paga, e-mail em minúsculas); **AFTER** roda **depois**, com a linha **já gravada** (ex.: **histórico** de nota).', 'Nota cheia (0,4): diferença + um uso de cada. Metade (0,2): diferença sem usos, ou só um lado. Zero (0): invertido.'),
      (v_atividade, 2, 3, 'Um UPDATE muda 30 parcelas: diga quantas vezes disparam um trigger FOR EACH ROW e um FOR EACH STATEMENT e explique.', 0.4, 'FOR EACH ROW dispara **30 vezes** (uma **por linha** afetada); FOR EACH STATEMENT dispara **1 vez** (uma **por comando**).', 'Nota cheia (0,4): os dois números + explicação. Metade (0,2): só um número correto. Zero (0): números trocados.'),
      (v_atividade, 3, 1, 'Diga quais são as duas peças de um trigger no PostgreSQL.', 0.2, 'Uma **função de trigger** (PL/pgSQL, RETURNS trigger) e o comando **CREATE TRIGGER**, que liga a função à tabela, ao evento e ao momento.', 'Nota cheia (0,2): as duas peças. Metade (0,1): só uma. Zero (0): nenhuma.'),
      (v_atividade, 3, 2, 'Escreva o cabeçalho da função de trigger (nome, tipo de retorno e linguagem) e a linha do CREATE TRIGGER que a executa.', 0.4, 'CREATE OR REPLACE FUNCTION registrar_historico_nota() **RETURNS trigger** LANGUAGE plpgsql AS $$ ... $$; e, no trigger: **EXECUTE FUNCTION** registrar_historico_nota(); (nome da função pode ser outro; sem parâmetros).', 'Nota cheia (0,4): RETURNS trigger sem parâmetros + EXECUTE FUNCTION. Metade (0,2): só um dos dois. Zero (0): RETURNS void, CALL ou função com parâmetros.'),
      (v_atividade, 3, 3, 'Explique o que guardam NEW, OLD e TG_OP e em quais eventos NEW e OLD existem.', 0.4, '**NEW** = linha **nova** (existe em **INSERT e UPDATE**); **OLD** = linha **antiga** (existe em **UPDATE e DELETE**); **TG_OP** = nome da operação (''INSERT'', ''UPDATE'' ou ''DELETE'').', 'Nota cheia (0,4): as três variáveis + eventos de NEW e OLD. Metade (0,2): explica as variáveis sem os eventos, ou só duas delas. Zero (0): NEW e OLD trocados.'),
      (v_atividade, 4, 1, 'Escreva o comando que acrescenta a coluna nota_final (de 0 a 10, com duas casas) à tabela matricula.', 0.2, 'ALTER TABLE matricula ADD COLUMN nota_final **numeric(4,2)** CHECK (nota_final **BETWEEN 0 AND 10**);', 'Nota cheia (0,2): ALTER TABLE ADD COLUMN numeric(4,2) com o CHECK. Metade (0,1): sem o CHECK ou com outro tipo numérico. Zero (0): CREATE TABLE ou tipo texto.'),
      (v_atividade, 4, 2, 'Escreva o CREATE TABLE historico_nota com matrícula, nota anterior, nota nova, usuário e data e hora preenchidos automaticamente.', 0.4, 'CREATE TABLE historico_nota (id_historico integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, id_matricula integer NOT NULL REFERENCES matricula (id_matricula), nota_anterior numeric(4,2), nota_nova numeric(4,2), alterado_por text NOT NULL **DEFAULT current_user**, alterado_em timestamptz NOT NULL **DEFAULT now()**);', 'Nota cheia (0,4): chave primária, FK para matricula, as duas notas e usuário/data com DEFAULT. Metade (0,2): falta a FK ou os DEFAULT. Zero (0): sem as notas ou sem relação.'),
      (v_atividade, 4, 3, 'Explique por que as colunas de usuário e de data usam DEFAULT current_user e now().', 0.4, 'Para que o banco grave **sozinho quem** alterou (usuário do banco) e **quando** (data e hora), sem depender de quem escreve o INSERT — base da **auditoria**.', 'Nota cheia (0,4): automático + quem e quando. Metade (0,2): só um. Zero (0): sem relação.'),
      (v_atividade, 5, 1, 'Diga qual momento (BEFORE ou AFTER) usar e por quê.', 0.2, '**AFTER**, porque o histórico registra uma alteração **já gravada** (e não precisa mudar nem barrar a linha).', 'Nota cheia (0,2): AFTER + motivo. Metade (0,1): só AFTER. Zero (0): BEFORE sem justificativa válida.'),
      (v_atividade, 5, 2, 'Escreva a função registrar_historico_nota que insere a matrícula, a nota antiga e a nova.', 0.4, 'CREATE OR REPLACE FUNCTION registrar_historico_nota() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO historico_nota (id_matricula, nota_anterior, nota_nova) VALUES (**NEW.id_matricula, OLD.nota_final, NEW.nota_final**); RETURN NEW; END; $$;', 'Nota cheia (0,4): RETURNS trigger + INSERT com OLD e NEW certos + RETURN. Metade (0,2): OLD/NEW trocados ou falta o RETURN. Zero (0): não grava no histórico.'),
      (v_atividade, 5, 3, 'Escreva o CREATE TRIGGER com UPDATE OF nota_final e um WHEN que só grava quando a nota mudou, e explique o uso de IS DISTINCT FROM.', 0.4, 'CREATE TRIGGER trg_historico_nota AFTER **UPDATE OF nota_final** ON matricula FOR EACH ROW **WHEN (OLD.nota_final IS DISTINCT FROM NEW.nota_final)** EXECUTE FUNCTION registrar_historico_nota(); — **IS DISTINCT FROM** trata o **NULL**: de NULL para 8,5 conta como mudança (com <> o resultado seria "desconhecido" e não gravaria).', 'Nota cheia (0,4): trigger correto com UPDATE OF e WHEN + explicação do NULL. Metade (0,2): trigger sem o WHEN ou sem a explicação. Zero (0): sem trigger.'),
      (v_atividade, 6, 1, 'Diga qual momento e qual evento o trigger deve usar.', 0.2, '**BEFORE UPDATE** (pode incluir DELETE), **FOR EACH ROW**, porque precisa **barrar** antes de gravar.', 'Nota cheia (0,2): BEFORE + UPDATE. Metade (0,1): só um. Zero (0): AFTER INSERT.'),
      (v_atividade, 6, 2, 'Escreva a função que barra a mudança de valor ou de vencimento de parcela já paga, com RAISE EXCEPTION.', 0.4, 'CREATE OR REPLACE FUNCTION proteger_parcela_paga() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF **OLD.data_pagamento IS NOT NULL** AND (**NEW.valor <> OLD.valor OR NEW.vencimento <> OLD.vencimento**) THEN **RAISE EXCEPTION** ''Parcela %/% já paga'', OLD.id_matricula, OLD.numero; END IF; RETURN NEW; END; $$;', 'Nota cheia (0,4): testa parcela paga + compara valor e vencimento OLD × NEW + RAISE EXCEPTION + RETURN NEW. Metade (0,2): falta uma das comparações, o RETURN NEW ou usa NOTICE. Zero (0): não confere se está paga.'),
      (v_atividade, 6, 3, 'Escreva o CREATE TRIGGER e explique o que acontece com o UPDATE quando a função chega ao RAISE EXCEPTION.', 0.4, 'CREATE TRIGGER trg_proteger_parcela_paga BEFORE UPDATE ON parcela FOR EACH ROW EXECUTE FUNCTION proteger_parcela_paga(); — o **RAISE EXCEPTION para** o comando e **desfaz** tudo: **nenhuma parcela é alterada** e o erro volta para quem executou o UPDATE.', 'Nota cheia (0,4): trigger correto + para e desfaz. Metade (0,2): só um. Zero (0): diz que a alteração é gravada.'),
      (v_atividade, 7, 1, 'Diga o que acontece quando a função devolve NEW.', 0.2, 'A **linha segue** e é gravada como está em **NEW** (inclusive com os ajustes feitos na função).', 'Nota cheia (0,2): segue/grava NEW. Zero (0): diz que cancela.'),
      (v_atividade, 7, 2, 'Escreva a função e o trigger BEFORE INSERT OR UPDATE em aluno que gravam o e-mail em minúsculas.', 0.4, 'CREATE OR REPLACE FUNCTION email_minusculo() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN **NEW.email := lower(NEW.email)**; **RETURN NEW**; END; $$; CREATE TRIGGER trg_email_minusculo **BEFORE INSERT OR UPDATE** ON aluno FOR EACH ROW EXECUTE FUNCTION email_minusculo();', 'Nota cheia (0,4): altera NEW com lower + RETURN NEW + trigger BEFORE INSERT OR UPDATE. Metade (0,2): falta o RETURN NEW, usa AFTER ou faz UPDATE na tabela. Zero (0): sem relação.'),
      (v_atividade, 7, 3, 'Explique o "UPDATE 0" do colega e diga o que a função deve devolver num trigger de DELETE para a exclusão seguir.', 0.4, 'A função do colega devolve **NULL** (ou não devolve NEW): num trigger BEFORE a linha é **pulada em silêncio**, nada é gravado e não aparece erro — por isso "UPDATE 0". Num trigger de **DELETE**, devolver **OLD** deixa a exclusão seguir.', 'Nota cheia (0,4): explica o RETURN NULL + RETURN OLD no DELETE. Metade (0,2): só um. Zero (0): nenhum.'),
      (v_atividade, 8, 1, 'Diga qual ferramenta usar na regra 1 e por quê.', 0.2, '**Restrição CHECK (valor > 0)**, porque a regra olha **só a própria linha** — é a primeira escolha, mais simples que um trigger.', 'Nota cheia (0,2): CHECK + motivo. Metade (0,1): só CHECK. Zero (0): trigger ou procedimento.'),
      (v_atividade, 8, 2, 'Diga qual ferramenta usar nas regras 2 e 3 e justifique cada uma.', 0.4, 'Regra 2: **trigger** (AFTER UPDATE), porque compara **OLD × NEW** e grava em **outra tabela** (histórico) para qualquer comando. Regra 3: **procedimento** (CALL matricular), porque é uma **ação do negócio** que o sistema pede.', 'Nota cheia (0,4): as duas escolhas com justificativa. Metade (0,2): uma certa, ou as duas sem justificativa. Zero (0): as duas trocadas.'),
      (v_atividade, 8, 3, 'Explique o risco de usar trigger demais no banco e o que fazer para diminuí-lo.', 0.4, 'O banco fica **"mágico"**: quem lê o comando **não vê o que mais acontece**, e erros ficam difíceis de achar. Para diminuir: **documentar** cada trigger (dicionário de dados e comentário no script) e usar trigger só quando restrição ou procedimento não resolvem.', 'Nota cheia (0,4): risco + como diminuir. Metade (0,2): só um. Zero (0): nenhum.'),
      (v_atividade, 9, 1, 'Diga como ver os triggers da tabela parcela no psql.', 0.2, '**\d parcela** no psql (os triggers aparecem no fim); no pgAdmin, Tables → parcela → Triggers.', 'Nota cheia (0,2): \d parcela (ou caminho do pgAdmin). Zero (0): SELECT na tabela ou comando inexistente.'),
      (v_atividade, 9, 2, 'Escreva os comandos que desligam e religam o trigger trg_proteger_parcela_paga e explique o cuidado ao usá-los.', 0.4, 'ALTER TABLE parcela **DISABLE TRIGGER** trg_proteger_parcela_paga; (correções) ALTER TABLE parcela **ENABLE TRIGGER** trg_proteger_parcela_paga; — Cuidado: enquanto está desligado, a **regra não vale**; usar só em **manutenção**, pelo menor tempo, e **religar** logo depois.', 'Nota cheia (0,4): os dois comandos + cuidado. Metade (0,2): só os comandos ou só o cuidado. Zero (0): DROP no lugar de desligar.'),
      (v_atividade, 9, 3, 'Escreva o comando que remove o trigger trg_historico_nota e explique o que acontece com a função dele.', 0.4, '**DROP TRIGGER trg_historico_nota ON matricula;** — a **função continua existindo**; para removê-la: DROP FUNCTION registrar_historico_nota();', 'Nota cheia (0,4): DROP TRIGGER com ON tabela + função continua. Metade (0,2): falta o ON matricula ou a explicação da função. Zero (0): DROP TABLE.'),
      (v_atividade, 10, 1, 'Explique o erro do trecho 1 e corrija.', 0.2, 'Função de trigger deve ser **RETURNS trigger** (sem parâmetros); com RETURNS void o CREATE TRIGGER dá **erro**. Correção: trocar para RETURNS trigger e devolver NEW (ou OLD).', 'Nota cheia (0,2): erro + correção. Metade (0,1): só um. Zero (0): nenhum.'),
      (v_atividade, 10, 2, 'Explique o problema do trecho 2 e corrija.', 0.4, 'O UPDATE dentro do trigger AFTER UPDATE na mesma tabela **dispara o trigger de novo**, em **laço**, até dar erro de profundidade. Correção: trigger **BEFORE** que altera **NEW** (NEW.nota_final := round(NEW.nota_final, 1); RETURN NEW;).', 'Nota cheia (0,4): laço + correção com BEFORE e NEW. Metade (0,2): só um. Zero (0): nenhum.'),
      (v_atividade, 10, 3, 'Explique o problema do trecho 3 e corrija.', 0.4, 'Sem WHEN e sem UPDATE OF, o trigger **grava histórico em todo UPDATE** da matrícula, **mesmo quando a nota não mudou**. Correção: AFTER **UPDATE OF nota_final** ... **WHEN (OLD.nota_final IS DISTINCT FROM NEW.nota_final)**.', 'Nota cheia (0,4): problema + correção com WHEN (UPDATE OF opcional). Metade (0,2): só um. Zero (0): nenhum.');
end $$;
